import type { TroubleCodeGuide } from "./trouble-code-data";

const manuals={label:"Toyota Highlander manuals and warranty guides",url:"https://www.toyota.com/owners/warranty-owners-manuals/",note:"Official Toyota model-year document lookup; confirm the VIN, engine, hybrid status and emissions certification"};
const tis={label:"Toyota Technical Information System",url:"https://techinfo.toyota.com/",note:"Toyota's current North American repair manuals, bulletins, wiring diagrams and calibration information"};
const waterTsb={label:"Toyota T-SB-0072-19 — Highlander connector corrosion",url:"https://static.nhtsa.gov/odi/tsbs/2019/MC-10162756-9999.pdf",note:"2014–2018 Highlander/Highlander Hybrid only; damaged or poorly sealed aftermarket windshield-deicer harnesses can admit water and cause drivability faults and DTCs including P0171, P0300 and P1604"};
const fuelTsb={label:"Toyota T-SB-0009-23 — fuel-pump pressure loss",url:"https://static.nhtsa.gov/odi/tsbs/2023/MC-10235216-9999.pdf",note:"Includes specifically listed 2017–2019 2GR Highlander and 2017–2019 Highlander Hybrid applications; VIN/VDS coverage must be verified"};
const o2Tsb={label:"Toyota T-SB-0001-10 Rev1 — P0138/P0158 diagnostic tips",url:"https://static.nhtsa.gov/odi/tsbs/2013/MC-10132202-9999.pdf",note:"Includes 2008–2010 Highlander 2GR-FE; uses companion codes and exact freeze-frame sensor values to distinguish the A/F sensor from the downstream O2 circuit"};
const crankTip={label:"Toyota T-TT-0465-17 — 2017 Highlander crank-sensor diagnostic support",url:"https://static.nhtsa.gov/odi/tsbs/2017/MC-10133656-9999.pdf",note:"2017 Highlander only; rough running, stalling, restart trouble or limp mode may be accompanied by P0300-family codes"};
const hybridCoil={label:"Toyota T-SB-0148-19 — Highlander Hybrid misfire/coil calibration",url:"https://static.nhtsa.gov/odi/tsbs/2019/MC-10168538-9999.pdf",note:"2017–2019 Highlander Hybrid 2GR-FXS only and only after Toyota diagnosis identifies a malfunctioning ignition coil"};
const evap2004={label:"Toyota EG048-04 — LEV II EVAP diagnostic supplement",url:"https://www.autocodes.com/uploads/toyota/EG048-04.pdf",note:"2004 Highlander is among the listed models; the supplement covers P0441, P0455 and related EVAP monitor testing"};
const catalystOld={label:"Toyota EG041-05 — 2001–2003 Highlander 2AZ-FE P0420/P0430 calibration",url:"https://charm.li/Toyota/2003/Highlander%202WD%20L4-2.4L%20%282AZ-FE%29/Repair%20and%20Diagnosis/Technical%20Service%20Bulletins/Customer%20Interest/Engine%20Controls%20-%20MIL%20ON%2FDTC%27s%20P0420%2FP0430%20Stored/",note:"Historical 2001–2003 2AZ-FE application only; verify calibration and completion history before applying the bulletin"};

const vehicle={name:"Toyota Highlander",kicker:"TOYOTA HIGHLANDER · ENGINE, HYBRID AND EMISSIONS DIAGNOSTICS",breadcrumb:"Toyota Highlander",about:"Toyota Highlander engine and emissions diagnostics",yearsIntro:"Highlander diagnostics span the first-generation 2.4L 2AZ-FE and 3.0L/3.3L MZ engines, later 2.7L 1AR-FE and 3.5L 2GR-family V6 engines, several hybrid systems, the 2020+ 2.5L A25A four-cylinder hybrid, and newer 2.4L turbo applications. Bank layout, fuel delivery, EVAP hardware, VVT control and safe hybrid procedures differ sharply. Confirm model year, VIN, engine code, hybrid status, drivetrain and emissions label before choosing tests or parts."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`toyota/highlander/${x.slug}`,vehicle});

export const troubleCodeHighlander:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Toyota Highlander: Bank 1 Catalyst Diagnosis",description:"Diagnose Highlander P0420 without guessing: identify Bank 1, test misfire, fuel trims, leaks and sensors, and check the narrow 2001–2003 2AZ-FE calibration case.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"A steady P0420 with normal power generally allows a short diagnostic trip, but avoid towing or sustained high load until misfire and restriction are excluded. Stop if the lamp flashes, the exhaust smells strongly of raw fuel, the converter rattles heavily or the engine loses power; those signs can indicate catalyst-damaging misfire or a broken/restricted substrate.",quickAnswer:"P0420 says the ECM measured inadequate oxygen-storage performance in the Bank 1 catalyst. It does not say that the rear oxygen sensor is bad, and it does not reveal why catalyst performance declined. Save freeze frame, repair any misfire or mixture fault, check oil/coolant consumption and exhaust leaks, then compare the upstream A/F sensor and downstream O2 response under the engine-specific Toyota test. One historical exception deserves a VIN/calibration check: EG041-05 addressed certain 2001–2003 Highlanders with the 2AZ-FE through revised ECM logic. That old four-cylinder bulletin does not apply to later V6, hybrid or turbo Highlanders.",symptoms:[{key:"normal",label:"MIL on but driving feels normal",response:"Preserve readiness and run prerequisite checks before replacing emissions parts."},{key:"flash",label:"MIL flashes under acceleration",response:"Back out of the throttle and diagnose the active misfire first."},{key:"rattle",label:"Metallic catalyst rattle",response:"Inspect for loose heat shields and broken substrate; test restriction if power falls."},{key:"repeat",label:"P0420 returns after converter replacement",response:"Recheck application, exhaust sealing, sensor circuits and the upstream cause."}],causes:[{cause:"Bank 1 catalyst has lost oxygen-storage capacity",evidence:"All prerequisites pass and Toyota catalyst test fails",firstTest:"Engine-correct catalyst monitor evaluation"},{cause:"Misfire or rich operation overheated the catalyst",evidence:"Historical misfire, fuel-trim codes or plug deposits",firstTest:"Resolve ignition/fueling fault first"},{cause:"Oil or coolant contamination",evidence:"Consumption, smoke, coolant loss or deposits",firstTest:"Mechanical and cooling-system checks"},{cause:"Leak near the Bank 1 sensor or catalyst",evidence:"Cold tick, soot trace or positive leak test",firstTest:"Inspect cold and perform a safe leak test"},{cause:"A/F or downstream O2 sensor/circuit fault",evidence:"Response or circuit values fail specification",firstTest:"Graph both sensors and test wiring"}],freezeFrame:["RPM, load, speed and coolant temperature","Companion and historical misfire or mixture codes","Bank 1 fuel trims and sensor data","Oil/coolant consumption history","Exhaust leak, rattle and restriction evidence","VIN, engine code and calibration ID"],steps:[{title:"Save the monitor evidence",detail:"Record confirmed, pending and permanent codes plus readiness before clearing."},{title:"Identify the engine and Bank 1",detail:"Do not use an online left/right answer across every four-cylinder, V6 and hybrid configuration."},{title:"Correct upstream faults",detail:"Misfire, abnormal fuel control and contamination can destroy a replacement converter."},{title:"Inspect the exhaust",detail:"Check joints, flex sections, shields and sensor bungs cold; hot exhaust can cause severe burns."},{title:"Test sensor behavior",detail:"Use Toyota's procedure and scan data rather than assuming the downstream sensor is the cause."},{title:"Verify the monitor",detail:"After repair, complete the correct drive pattern and confirm no pending P0420."}],dontReplace:"Do not install a converter from one scan result or apply EG041-05 to every Highlander. Confirm the old 2AZ-FE calibration branch by year, engine and calibration history; all other vehicles require normal evidence-based catalyst diagnosis.",yearNotes:["2001–2003 2AZ-FE: EG041-05 describes revised ECM logic for a narrow historical population.","V6 Highlanders have two banks; P0420 is Bank 1 while P0430 is Bank 2.","Hybrid engine operation and monitor enable conditions differ because the engine may stop during normal vehicle operation.","Federal versus California certification and AWD/FWD packaging can change the legal exhaust assembly."],faqs:[{question:"Does P0420 prove the converter is bad?",answer:"No. It reports monitor performance; upstream faults, leaks and sensor problems must be excluded."},{question:"Which side is Bank 1?",answer:"The bank containing cylinder 1. Confirm the exact engine service diagram instead of using vehicle left/right alone."},{question:"Can I drive with it?",answer:"Usually briefly if the lamp is steady and operation is normal, but avoid heavy load and stop for flashing, rattling or power loss."},{question:"Does the 2001–2003 bulletin cover my V6?",answer:"No. EG041-05 identifies the 2AZ-FE application."},{question:"Will a rear O2 sensor fix it?",answer:"Only if circuit and response testing proves that sensor or its wiring is faulty."},{question:"Can oil burning cause P0420?",answer:"Yes. Oil ash can contaminate catalyst material and a new converter will not cure the consumption source."},{question:"Why did the code return after parts?",answer:"The original engine fault, an exhaust leak, wrong emissions application or incomplete monitor diagnosis may remain."},{question:"What confirms repair?",answer:"Normal upstream operation plus a completed catalyst monitor with no pending or permanent fault progression."}],deepDive:[{heading:"The early 2AZ-FE calibration case is narrow",paragraphs:["EG041-05 names 2001–2003 Highlander vehicles with the 2AZ-FE. It calls for checking the authorized-modifications label and calibration ID before reprogramming.","A later Highlander with the same code does not inherit that repair. A bulletin is a conditional diagnostic branch, not proof that every listed symptom shares one cause."]},{heading:"Hybrid operation changes the road test",paragraphs:["A hybrid Highlander may shut the gasoline engine off while the vehicle remains ready. Catalyst temperature and monitor enable conditions therefore cannot be inferred from road speed alone.","Use engine-run data and the Toyota confirmation procedure; do not force unsafe service-mode operation merely to make a generic drive cycle run."]},{heading:"Protect the replacement",paragraphs:["A converter can be the failed component and still not be the root cause. Misfire, rich fueling, coolant entry and oil consumption should be addressed before replacement.","Match the emissions label and VIN. A part that bolts in may not be the correct monitored or legally approved assembly."]}],sources:[catalystOld,manuals,tis]}),

article({slug:"p0171",code:"P0171",title:"P0171 Code Toyota Highlander: Bank 1 Lean Diagnosis",description:"Diagnose Highlander P0171 with bank-to-bank trims, MAF and fuel-pressure tests, plus exact 2014–2018 connector and 2017–2019 fuel-pump bulletin checks.",definition:"System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid towing, hard acceleration and long trips while the engine hesitates or fuel trims are strongly positive. Stop if it stalls, loses fuel pressure, knocks, overheats or the lamp flashes. A mildly elevated trim with smooth operation may allow a short test drive while live data is recorded.",quickAnswer:"P0171 means the ECM reached the lean correction threshold for Bank 1; it does not automatically mean an oxygen sensor failed. Compare both banks at idle and raised rpm. Both banks lean suggests measured-air error, a broad intake leak or weak fuel delivery; one bank lean points toward a bank-specific gasket, exhaust leak, injector or sensor circuit. Two Highlander-specific checks matter: T-SB-0072-19 covers water intrusion caused by certain aftermarket windshield-deicer harnesses on 2014–2018 vehicles, while T-SB-0009-23 covers fuel-pressure loss on specifically listed 2017–2019 Highlander/Highlander Hybrid applications. Verify VIN/VDS and symptoms before using either branch.",symptoms:[{key:"idle",label:"Rough mostly at idle",response:"Compare trims at idle and 2,500 rpm; prioritize unmetered air or purge flow if they improve."},{key:"load",label:"Hesitation under load",response:"Compare commanded and actual fuel pressure; do not continue a low-pressure pull."},{key:"both",label:"P0171 and P0174 together",response:"Look for causes shared by both banks before disturbing individual injectors."},{key:"water",label:"Fault followed windshield accessory work",response:"On 2014–2018, inspect the exact connector/harness conditions in T-SB-0072-19."}],causes:[{cause:"Unmetered air after the MAF",evidence:"Trims most positive at idle and improve with rpm",firstTest:"Smoke-test intake and PCV plumbing"},{cause:"MAF under-reporting or intake contamination",evidence:"Both-bank trims and airflow data disagree with load",firstTest:"Inspect duct/filter and compare MAF data"},{cause:"Fuel-pressure or delivery loss",evidence:"Lean under load, extended crank or low measured pressure",firstTest:"Compare commanded/actual and manual pressure as specified"},{cause:"Bank 1 exhaust leak or injector imbalance",evidence:"One-bank trim split, cold tick or contribution result",firstTest:"Leak test and injector balance"},{cause:"A43 ECM connector water intrusion",evidence:"2014–2018 match with aftermarket deicer harness/water evidence",firstTest:"Follow T-SB-0072-19 inspection"}],freezeFrame:["Short- and long-term trim for both banks","RPM, load, coolant temperature and speed","MAF airflow and calculated load","Commanded/actual fuel pressure where supported","A/F sensor data and misfire counters","Starting history, rain/accessory work and companion codes"],steps:[{title:"Preserve both-bank data",detail:"Save freeze frame and graph trims before clearing adaptations."},{title:"Confirm the configuration",detail:"Four-cylinder and V6/hybrid fuel systems do not share every test point."},{title:"Compare idle with raised rpm",detail:"A trim change helps separate an intake leak from delivery or metering problems."},{title:"Smoke-test measured air",detail:"Inspect the complete post-MAF tract, brake-booster and PCV paths without flammable spray."},{title:"Test fuel pressure under the fault condition",detail:"Use the VIN-correct high- and low-side procedure; pressure at idle alone may mislead."},{title:"Inspect bulletin branches only when matched",detail:"Check the aftermarket deicer connector path and fuel-pump program by exact applicability."},{title:"Prove the repair",detail:"Reset only after saving evidence, then confirm both banks remain controlled through load changes."}],dontReplace:"Do not replace Bank 1's A/F sensor because the code says Bank 1. The sensor may be accurately reporting extra air or insufficient fuel. Likewise, do not assume every 2017–2019 vehicle qualifies for the fuel-pump program; confirm the bulletin's VIN/VDS and test results.",yearNotes:["2014–2018: T-SB-0072-19 concerns connector corrosion related to a damaged or poorly sealed aftermarket windshield-deicer harness.","2017–2019: T-SB-0009-23 includes specific Highlander and Highlander Hybrid fuel-pump applications.","A four-cylinder has one bank; a V6 provides useful Bank 1 versus Bank 2 comparison.","Hybrid and direct-injection systems require powertrain-specific pressure and safety procedures."],faqs:[{question:"Does P0171 mean a bad oxygen sensor?",answer:"No. The A/F sensor may be correctly reporting a lean mixture caused by air, fuel or exhaust faults."},{question:"What if P0174 is also stored?",answer:"Both banks lean moves shared air metering, intake and fuel supply higher on the list."},{question:"Can a loose gas cap cause P0171?",answer:"Usually not by itself; gas-cap faults more directly affect the EVAP monitor."},{question:"Can I clean the MAF?",answer:"Inspect data and contamination first; use only an approved method and never touch the sensing element."},{question:"Is the fuel pump automatically covered?",answer:"No. Coverage and remedy depend on the exact VIN/VDS, year, application and program terms."},{question:"Why check windshield accessory wiring?",answer:"Toyota documented water intrusion through certain aftermarket deicer harness installations on 2014–2018 models."},{question:"Can an intake leak damage the engine?",answer:"Severe lean operation can cause poor combustion and catalyst stress, especially under load."},{question:"What proves the repair?",answer:"Stable trims on both banks under idle and load, normal pressure and no pending P0171."}],deepDive:[{heading:"Let the bank split choose the next test",paragraphs:["On a V6, a large Bank 1/Bank 2 difference is localization evidence. Inspect the affected bank's intake sealing, exhaust ahead of its sensor and injector contribution.","Nearly equal positive correction suggests a shared problem. Replacing one bank sensor in that situation ignores the strongest clue."]},{heading:"Fuel pressure must be tested when demand rises",paragraphs:["A pump can look adequate at idle yet fail during acceleration or after heat soak. Preserve the load and temperature from freeze frame and reproduce safely.","T-SB-0009-23 has defined applicability and procedures. It supports a fuel-pressure branch; it does not turn P0171 into a pump verdict."]},{heading:"Connector corrosion can imitate multiple systems",paragraphs:["Water at an ECM connector can produce a mixture of starting, fuel-pressure, communication and misfire symptoms. That code diversity is a reason to inspect common electrical paths.","The Toyota bulletin ties this branch to specific aftermarket windshield-deicer harness sealing. Do not condemn the ECM merely because water is suspected."]}],sources:[waterTsb,fuelTsb,manuals,tis]}),

article({slug:"p0441",code:"P0441",title:"P0441 Code Toyota Highlander: Incorrect EVAP Purge Flow",description:"Diagnose Highlander P0441 by testing purge flow, cap sealing, canister valves and tank pressure—not by replacing the gas cap blindly.",definition:"Evaporative Emission Control System Incorrect Purge Flow",severity:"Service soon",driveAdvice:"P0441 normally does not require stopping immediately when the Highlander runs normally and there is no fuel leak. Park outside and stop driving if you smell strong raw fuel, see liquid fuel, have refueling spit-back or notice a damaged tank or line. Do not smoke or create sparks around EVAP testing.",quickAnswer:"P0441 means the ECM's commanded purge test did not produce the expected tank-pressure response. The fault can be too little purge, purge when none was commanded, a leak that prevents vacuum from developing, a blocked vent path or misleading pressure-sensor data. Start by saving related P0455/P0456/P0446 codes and fuel level, then test the purge valve for sealing and commanded flow, inspect the cap and hoses, and use a low-pressure smoke test with bidirectional valve control. Toyota EG048-04 supplies an older LEV II monitor supplement that includes the 2004 Highlander; it should not be treated as the plumbing diagram for every generation.",symptoms:[{key:"cap",label:"Code appeared after refueling",response:"Record cap condition and seal before disturbing it; inspect filler-neck sealing surface."},{key:"idle",label:"Rough or hard start after filling",response:"Test whether the purge valve leaks vapor into the intake when commanded closed."},{key:"pair",label:"P0441 plus P0455/P0456",response:"Smoke-test and watch tank pressure; a system leak can prevent correct purge response."},{key:"odor",label:"Fuel odor or visible wetness",response:"Stop, ventilate and inspect safely for a liquid-fuel leak before running tests."}],causes:[{cause:"Purge valve leaking or not flowing when commanded",evidence:"Vacuum/flow exists at the wrong command state",firstTest:"Bench/in-vehicle sealing and bidirectional test"},{cause:"Loose, damaged or wrong fuel cap",evidence:"Seal or filler-neck defect and failed pressure hold",firstTest:"Inspect seal and test cap to specification"},{cause:"Split, pinched or disconnected vapor hose",evidence:"Visible damage or smoke outlet",firstTest:"Low-pressure smoke test"},{cause:"Vent valve/canister restriction or saturation",evidence:"Poor vent response, refueling issue or liquid fuel",firstTest:"Command vent and test flow"},{cause:"Tank-pressure sensor/circuit error",evidence:"Biased, implausible or unresponsive scan value",firstTest:"Compare pressure PID with controlled pressure"}],freezeFrame:["Fuel level and ambient temperature","Tank/vapor pressure PID","Purge command and engine load","Companion EVAP and mixture codes","Recent refueling or repeated topping-off","Year, engine and EVAP system layout"],steps:[{title:"Do not erase the refueling context",detail:"Record fuel level, temperature, codes and whether the cap was just opened."},{title:"Inspect without assuming",detail:"Check the cap, filler neck and accessible hoses but do not call appearance a pressure test."},{title:"Test purge sealing",detail:"A valve that leaks closed can cause post-refuel hard starting and incorrect flow."},{title:"Command purge and vent",detail:"Watch tank pressure response with a capable scan tool and the correct service procedure."},{title:"Smoke-test gently",detail:"Use regulated EVAP pressure; shop air can damage valves, tank or canister."},{title:"Complete the EVAP monitor",detail:"Verification may require the prescribed fuel-level and temperature window."}],dontReplace:"Do not buy a cap, purge valve and charcoal canister as a bundle. P0441 is a flow-result code, and each component can be tested. Avoid flooding the canister with smoke fluid or pressure, and never bypass hybrid/high-voltage precautions to reach components.",yearNotes:["2004 Highlander: EG048-04 documents the LEV II system and threshold logic for that listed application.","Later generations may use different pumps, valves and self-test strategies; follow the VIN-correct diagram.","Repeatedly topping off after nozzle shutoff can send liquid fuel toward the canister.","Hybrid status does not make gasoline vapor harmless; normal fire and ventilation precautions still apply."],faqs:[{question:"Is P0441 just a loose gas cap?",answer:"It can involve cap sealing, but purge valves, hoses, venting, pressure sensing and the canister are also possible."},{question:"Can P0441 cause rough starting after refueling?",answer:"Yes, a purge valve leaking vapor into the intake can disturb the mixture after a fill."},{question:"Can I drive?",answer:"Usually briefly if no fuel leak or odor exists and operation is normal."},{question:"Will clearing it fix it?",answer:"No. Clearing removes monitor evidence and readiness; the fault returns when enable conditions repeat."},{question:"Why is fuel level important?",answer:"Toyota EVAP monitors run only in defined conditions, and a very full or nearly empty tank can delay testing."},{question:"Can overfilling cause trouble?",answer:"Repeated topping-off can saturate a charcoal canister designed to handle vapor, not liquid fuel."},{question:"Can I use compressed air?",answer:"Not directly. EVAP testing needs safely regulated low pressure and approved equipment."},{question:"What confirms repair?",answer:"Correct commanded pressure response and a completed EVAP monitor without pending codes."}],deepDive:[{heading:"Purge flow and system sealing overlap",paragraphs:["The ECM expects a pressure change when purge is commanded. A large leak can make a good purge valve look ineffective because the system cannot hold vacuum.","Conversely, a purge valve that leaks while closed can disturb idle without creating an obvious external smoke outlet. Test command state and sealing separately."]},{heading:"A cap inspection is evidence, not a verdict",paragraphs:["Look for a hardened, cut or folded seal and corrosion or damage at the filler neck. Preserve the original cap position if the code followed refueling.","A new cap cannot repair a cracked hose, blocked vent or biased pressure sensor. Confirm the entire system response after any cap repair."]},{heading:"Use the correct generation diagram",paragraphs:["EG048-04 is valuable for understanding the listed 2004 LEV II system, but Highlander hardware evolved across generations.","Trace hoses and valve locations using the VIN-correct Toyota information instead of forcing an older schematic onto a newer vehicle."]}],sources:[evap2004,manuals,tis]}),

article({slug:"p0455",code:"P0455",title:"P0455 Code Toyota Highlander: Find the Large EVAP Leak",description:"Find a Highlander P0455 large EVAP leak with cap, hose, vent, purge and smoke tests, including the limited 2004 Toyota monitor supplement.",definition:"Evaporative Emission Control System Leak Detected (Gross Leak)",severity:"Service soon",driveAdvice:"A large EVAP leak normally affects emissions rather than braking or steering, but gasoline vapor is a fire concern. Stop and park outdoors if there is strong fuel odor, visible wet fuel, tank damage or refueling spit-back. Do not test near ignition sources, and do not pressurize the tank with unregulated shop air.",quickAnswer:"P0455 means the EVAP self-test could not create or retain the expected pressure change, consistent with a gross leak or a valve that leaves the system open. Begin with the circumstances: did it set after refueling or after fuel-tank, pump, exhaust or rear-body work? Inspect the cap and filler neck, then command the purge and vent devices while watching tank pressure. Isolate sections and introduce approved low-pressure smoke. On a 2004 Highlander, EG048-04 provides Toyota's LEV II thresholds and system description; later Highlanders may use different leak-detection hardware and require their own diagram.",symptoms:[{key:"refuel",label:"MIL followed a fill-up",response:"Preserve cap position and inspect its seal, tether interference and filler-neck surface."},{key:"repair",label:"Code followed tank or pump work",response:"Inspect disconnected, pinched and misrouted lines before ordering components."},{key:"odor",label:"Strong gasoline odor",response:"Treat as a possible liquid leak; stop and ventilate before electrical testing."},{key:"repeat",label:"New cap did not fix it",response:"Test vent/purge sealing and smoke-test the rest of the system."}],causes:[{cause:"Cap absent, loose, damaged or wrong",evidence:"Seal defect or cap fails pressure/vacuum check",firstTest:"Inspect filler neck and test the cap"},{cause:"Large disconnected or split vapor line",evidence:"Recent work, visual opening or obvious smoke outlet",firstTest:"Trace lines and low-pressure smoke test"},{cause:"Vent valve stuck open",evidence:"System will not seal when commanded closed",firstTest:"Bidirectional command and sealing test"},{cause:"Purge valve stuck open",evidence:"Intake vacuum reaches EVAP when purge is off",firstTest:"Closed-state vacuum/flow test"},{cause:"Canister, tank or pump-module seal leak",evidence:"Localized smoke or pressure decay",firstTest:"Sectional isolation test"}],freezeFrame:["Fuel level and ambient/soak temperature","Tank pressure before and during monitor","Purge and vent commands","Other EVAP circuit/flow codes","Recent refueling or underbody work","Visible collision, road-debris or rodent damage"],steps:[{title:"Record before touching the cap",detail:"The cap's found condition is evidence, especially immediately after refueling."},{title:"Inspect the large openings",detail:"Check cap, filler path, accessible hoses and service connections."},{title:"Verify valve sealing",detail:"Command vent closed and purge off; confirm the system can be isolated."},{title:"Introduce regulated smoke",detail:"Use approved EVAP equipment and watch the entire system, including the top of the tank."},{title:"Separate leak from sensor error",detail:"Confirm tank-pressure response to a controlled pressure change."},{title:"Verify in the correct window",detail:"The EVAP monitor may need an overnight soak, suitable temperature and mid-range fuel level."}],dontReplace:"Do not assume 'gross leak' names a hole in the tank. A loose cap or valve held open can create the same monitor result. Replace only the part that fails a sealing, command, circuit or smoke test.",yearNotes:["2004: EG048-04 includes Highlander and documents that generation's LEV II EVAP monitor.","Later systems can package the canister, pump and valves differently; parts are not interchangeable by code alone.","Work near the tank or rear exhaust can disturb vapor hoses and electrical connectors.","Hybrid battery safety does not replace fuel-vapor safety; follow both sets of precautions where applicable."],faqs:[{question:"Is P0455 always the gas cap?",answer:"No. The cap is an early check, but open valves, hoses, seals, canister and tank faults can all create a large leak result."},{question:"Can I drive?",answer:"Usually briefly if no fuel odor, wetness or drivability problem exists; stop for evidence of liquid fuel."},{question:"Can overfilling cause it?",answer:"It can damage or saturate EVAP components, though a gross-leak result still needs testing."},{question:"Why did a new cap fail to help?",answer:"The leak may be elsewhere, the filler neck may be damaged, or the replacement cap may not seal correctly."},{question:"Can smoke damage the system?",answer:"Yes, if pressure or fluid volume is excessive; use regulated EVAP equipment."},{question:"Why will the monitor not run?",answer:"Fuel level, temperature, soak time and other faults may block its enable conditions."},{question:"Does P0455 identify the leak location?",answer:"No. It describes leak magnitude as inferred by the monitor."},{question:"What proves repair?",answer:"The system holds the prescribed pressure response and the EVAP monitor completes without a pending code."}],deepDive:[{heading:"Found condition matters after refueling",paragraphs:["Do not tighten the cap before recording whether it was loose, cross-threaded or obstructed. Otherwise the best clue disappears.","Inspect the sealing face as well as the cap. Rust, dents or a foreign object can prevent a good cap from sealing."]},{heading:"A valve can look like a hole",paragraphs:["The ECM expects the EVAP system to close for part of its test. If the vent or purge valve cannot seal, pressure escapes through a normal passage.","Command and circuit testing should precede canister replacement. Listen for a click only as a clue; it does not prove a valve seals."]},{heading:"Rear-body work changes the suspect list",paragraphs:["Fuel-pump access, tank removal, collision repair, trailer-hitch work and road debris can disturb hoses or connectors.","Ask what changed before the lamp appeared. That history often makes smoke testing faster and less invasive."]}],sources:[evap2004,manuals,tis]}),

article({slug:"p0300",code:"P0300",title:"P0300 Code Toyota Highlander: Random Misfire Diagnosis",description:"Diagnose Highlander P0300 using cylinder counters, trims and compression, with exact 2017 crank-sensor, 2014–2018 water-intrusion and hybrid coil bulletin limits.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"Stop sustained driving when the malfunction lamp flashes, the engine shakes strongly, power drops or raw fuel is evident. An active misfire can overheat the catalysts quickly. A steady lamp with smooth operation may allow a short diagnostic trip, but avoid towing and hard acceleration. Hybrid vehicles require correct READY-state and high-voltage precautions.",quickAnswer:"P0300 records crankshaft-speed disturbances spread across cylinders or not yet attributable to one cylinder. Start with cylinder-specific counts and companion P0301–P0306 codes at the same temperature and load as freeze frame. One cylinder suggests plug, coil, injector or sealing tests; several cylinders on one bank suggest bank-specific air, fueling or timing; both banks suggest shared fuel, air, crank-signal or mechanical causes. Highlander has three narrow official branches worth checking: 2017 crank-position-sensor diagnostic support, 2014–2018 connector corrosion associated with certain aftermarket windshield-deicer harnesses, and a 2017–2019 Highlander Hybrid coil/calibration bulletin that applies only after Toyota diagnosis identifies a failed coil.",symptoms:[{key:"flash",label:"Lamp flashes and engine shakes",response:"Reduce load and stop; diagnose before catalyst damage occurs."},{key:"cold",label:"Misfire only on cold start",response:"Save counts immediately; inspect ignition, injector behavior and mechanical sealing cold."},{key:"restart",label:"Stall or failed stop/start restart",response:"On a matched 2017, include the crank-sensor diagnostic branch."},{key:"rain",label:"Multiple faults after rain/accessory work",response:"On 2014–2018, inspect the deicer-harness water path described by Toyota."}],causes:[{cause:"Worn/fouled plugs or weak coil",evidence:"Count follows coil swap or plug condition is abnormal",firstTest:"Inspect in cylinder order and perform a controlled swap"},{cause:"Injector delivery or fuel-pressure loss",evidence:"Contribution imbalance, lean codes or low pressure",firstTest:"Pressure and injector balance tests"},{cause:"Intake/purge air fault",evidence:"Positive trims, idle sensitivity or post-refuel pattern",firstTest:"Smoke-test and purge-sealing test"},{cause:"Mechanical sealing or cam-timing problem",evidence:"Low relative compression, noise or correlation codes",firstTest:"Relative compression then leak-down/timing checks"},{cause:"Crank signal or connector water intrusion",evidence:"Matched year/symptoms and signal/connector evidence",firstTest:"Follow exact Toyota tip/bulletin"}],freezeFrame:["Cylinder-specific misfire counts","RPM, load, coolant temperature and speed","Fuel trims for both banks","Fuel pressure and MAF data","Crank/cam and stop-start related codes","Weather, recent windshield accessory work and fuel history"],steps:[{title:"Save the first failure record",detail:"Do not clear the cold-start, load and cylinder pattern you need to reproduce."},{title:"Classify the distribution",detail:"One cylinder, one bank and all-cylinder patterns lead to different tests."},{title:"Inspect plugs, boots and connectors",detail:"Keep removed plugs labeled; deposits can expose coolant, oil or mixture differences."},{title:"Separate ignition, fuel and compression",detail:"Use controlled swaps and contribution tests; stop swapping once evidence stays with the cylinder."},{title:"Review Highlander-specific branches",detail:"Apply the 2017 crank tip, 2014–2018 water bulletin or hybrid coil bulletin only to exact matches."},{title:"Verify under the original condition",detail:"Confirm counters remain quiet cold and under safe load, with no pending code."}],dontReplace:"Do not install six coils because P0300 says 'multiple.' Toyota's hybrid bulletin still requires diagnosis to identify a malfunctioning coil, and its calibration is limited to listed 2017–2019 Highlander Hybrid vehicles. The 2017 crank tip and connector bulletin are conditional diagnostic paths, not automatic part approvals.",yearNotes:["2017 Highlander: T-TT-0465-17 links certain rough-running, stalling/restart and limp-mode conditions to crank-sensor diagnostic support.","2014–2018: T-SB-0072-19 identifies connector corrosion tied to certain aftermarket windshield-deicer harness installations.","2017–2019 Highlander Hybrid 2GR-FXS: T-SB-0148-19 applies only after misfire diagnosis indicates a faulty ignition coil.","Four-cylinder, V6, hybrid and turbo engines use different ignition, injection and timing strategies."],faqs:[{question:"Can I drive with P0300?",answer:"Not with a flashing lamp, heavy shaking, raw-fuel odor or power loss. Those conditions threaten the catalysts and may be unsafe."},{question:"Will plugs fix it?",answer:"Only if inspection and testing show worn, fouled, damaged or incorrectly specified plugs."},{question:"Why is there no cylinder code?",answer:"The misfire may be distributed or inconsistent; live counters can still reveal a leading cylinder."},{question:"Does the 2017 tip mean replace the crank sensor?",answer:"No. It directs diagnostic support for a defined symptom population; circuit and signal evidence still matter."},{question:"Does the hybrid bulletin replace all coils?",answer:"No. Toyota's procedure first requires diagnosis indicating a malfunctioning coil."},{question:"Can low fuel pressure cause random misfire?",answer:"Yes, especially under load; check companion lean codes and measured pressure."},{question:"Should I clear it to see if it returns?",answer:"Save freeze frame and counters first. Clearing can erase the only record of an intermittent cold event."},{question:"What confirms repair?",answer:"Stable cylinder counts through the original temperature/load condition and no pending P0300."}],deepDive:[{heading:"Cylinder distribution is more valuable than the code title",paragraphs:["P0300 does not mean every cylinder is failing equally. Graph counts during idle, raised rpm and a safe loaded event to see whether one cylinder or bank leads.","A one-bank pattern can point toward an intake seal, fuel delivery or valve-timing issue that six new coils cannot repair."]},{heading:"The 2017 crank-sensor branch includes restart behavior",paragraphs:["Toyota's tech tip names rough running, limp mode, stalling after start and stop/start restart failure as possible companion conditions.","Match the year and symptom, then test the signal and circuit through current Toyota information. A code mention alone is not a replacement instruction."]},{heading:"Aftermarket wiring can create an unrelated-looking code cluster",paragraphs:["T-SB-0072-19 describes water entry associated with damaged or poorly sealed windshield-deicer harnesses. Corrosion at a shared connector can disturb several systems at once.","Inspect before replacing control modules or fuel components, and repair the water path as well as the corrosion so the fault does not return."]}],sources:[crankTip,waterTsb,hybridCoil,fuelTsb,manuals]}),

article({slug:"p0016",code:"P0016",title:"P0016 Code Toyota Highlander: Crank–Cam Correlation Test",description:"Diagnose Highlander P0016 by identifying the engine and bank, checking oil/VVT control and proving mechanical timing before replacing sensors.",definition:"Crankshaft Position–Camshaft Position Correlation (Bank 1 Sensor A)",severity:"Diagnose promptly",driveAdvice:"Do not continue driving if P0016 arrives with chain rattle, low oil pressure, severe roughness, stalling or a no-start. A correlation fault can reflect mechanical timing movement that worsens without warning. With normal oil level, no noise and smooth operation, move the Highlander only as needed for diagnosis and avoid high rpm or towing.",quickAnswer:"P0016 means the measured relationship between the crankshaft and Bank 1 intake camshaft fell outside the ECM's expected window. The code cannot distinguish a biased sensor from dirty/low oil, a sticking oil-control valve, wiring, a VVT actuator problem or slipped mechanical timing. Confirm the exact engine and Bank 1 layout, save cam-command and actual-angle data, verify oil level/condition/pressure, then test circuits and oil-control response. If commanded and actual position cannot be reconciled, establish true mechanical timing before buying sensors. Hybrid service mode and high-voltage safety require Toyota procedures.",symptoms:[{key:"noise",label:"Rattle at start or continuously",response:"Stop unnecessary running and check oil pressure and mechanical timing promptly."},{key:"nostart",label:"Extended crank or no-start",response:"Preserve sync and rpm data; perform relative compression before repeated cranking."},{key:"normal",label:"MIL on but engine smooth",response:"Check oil, freeze frame, pending codes and sensor/VVT data without clearing."},{key:"after",label:"Code followed timing or engine work",response:"Recheck connector routing, reluctor alignment and mechanical timing first."}],causes:[{cause:"Low, wrong, degraded or aerated engine oil",evidence:"Level/condition wrong or pressure response abnormal",firstTest:"Correct oil verification and pressure test"},{cause:"Sticking oil-control valve or restricted VVT passage",evidence:"Commanded angle changes but actual response is slow/erratic",firstTest:"Bidirectional VVT and valve/circuit test"},{cause:"Crank/cam sensor or wiring fault",evidence:"Dropout, implausible waveform or circuit defect",firstTest:"Scope signals and inspect power/ground/harness"},{cause:"Chain/belt timing or actuator movement",evidence:"Persistent offset, noise or failed mechanical alignment",firstTest:"Verify base timing with engine-specific procedure"},{cause:"Reluctor/trigger damage or installation error",evidence:"Code after repair or waveform phase abnormal",firstTest:"Inspect trigger installation and waveform relationship"}],freezeFrame:["Engine speed, load and coolant temperature","Commanded and actual Bank 1 intake cam angle","Oil temperature/pressure information where available","P0017/P0018/P0019 and VVT circuit codes","Cranking rpm, synchronization and relative compression","Oil service and recent timing/engine repair history"],steps:[{title:"Identify Bank 1 Sensor A correctly",detail:"Sensor A normally denotes the intake cam, but location and access depend on the exact engine."},{title:"Inspect oil before electrical parts",detail:"Record level, grade, contamination and filter/service history; correct low pressure urgently."},{title:"Graph command versus response",detail:"A capable scan tool can show whether the VVT system follows ECM commands."},{title:"Test circuits and waveforms",detail:"Look for heat, oil or repair damage and compare crank/cam phase, not merely resistance."},{title:"Prove mechanical timing",detail:"If offset persists, verify base timing and actuator integrity before replacing sensors."},{title:"Relearn and verify correctly",detail:"Perform required initialization, then reproduce the original cold/hot condition."}],dontReplace:"Do not replace crank and cam sensors as a pair from P0016 alone. Sensors often report a real timing or oil-control problem. A new sensor cannot correct low oil pressure, a restricted control passage, a moved reluctor or a slipped chain/belt.",yearNotes:["Early 2.4L and MZ-era engines use different timing architecture from later 2GR, A25A and turbo engines.","Bank 1 means the bank containing cylinder 1; do not infer front/rear across every V6 generation.","Hybrid engine start/stop behavior changes when correlation data can be captured; use Toyota READY-state precautions.","Recent engine, timing-cover or sensor work materially increases the likelihood of installation or harness issues."],faqs:[{question:"Does P0016 mean the timing chain is bad?",answer:"Not necessarily. Oil/VVT control, sensors, wiring, reluctors and mechanical timing can all create correlation error."},{question:"Can low oil cause it?",answer:"Yes. VVT actuators depend on correct oil level, viscosity, cleanliness and pressure."},{question:"Can I drive?",answer:"Avoid driving with rattle, oil-pressure warning, stalling or severe roughness; otherwise limit movement to diagnosis."},{question:"Which cam is Sensor A?",answer:"It generally identifies the intake cam, but verify the engine-specific Toyota diagram."},{question:"Should I replace both sensors?",answer:"No. Test signal integrity and mechanical phase first."},{question:"Can a weak battery set it?",answer:"Low cranking speed can complicate starting data, but persistent correlation still needs phase and circuit testing."},{question:"Why did it appear after repair?",answer:"Connector swaps, wiring damage, trigger installation and mechanical timing should move to the top of the list."},{question:"What proves repair?",answer:"Stable crank–cam phase, correct VVT response and no pending correlation code through cold and warm operation."}],deepDive:[{heading:"Correlation is a relationship, not a component name",paragraphs:["The ECM compares two rotating references. Either signal can be electrically wrong, or both sensors can be truthful while the cam is mechanically out of phase.","That is why a scope relationship and base-timing check can be more decisive than installing a sensor and waiting."]},{heading:"Oil inspection needs more than a dipstick glance",paragraphs:["Confirm grade, level, contamination, filter history and pressure when symptoms warrant. Aerated or restricted oil can make cam response unstable.","Correct the oil-pressure cause before repeatedly commanding VVT. Continued operation with inadequate lubrication can expand the repair dramatically."]},{heading:"Hybrid precautions change access and testing",paragraphs:["A stopped gasoline engine does not mean a hybrid is powered down. Follow Toyota's shutdown and waiting procedures before intrusive work.","Use the specified service mode only when required. Unnecessary forced running can create unsafe conditions or misleading monitor behavior."]}],sources:[manuals,tis]}),

article({slug:"p0128",code:"P0128",title:"P0128 Code Toyota Highlander: Thermostat and Warm-Up Test",description:"Diagnose Highlander P0128 with cold-soak temperature comparison and a recorded warm-up curve; separate thermostat, sensor, fan and cooling-system faults.",definition:"Coolant Thermostat (Coolant Temperature Below Thermostat Regulating Temperature)",severity:"Service soon",driveAdvice:"P0128 usually means the engine warms too slowly rather than overheats, but the code is not permission to ignore the temperature gauge. Stop for overheating, steam, coolant loss, heater suddenly going cold or a temperature warning. With stable coolant level and no overheating, a short diagnostic drive is generally reasonable.",quickAnswer:"P0128 sets when coolant temperature remains below the ECM's expected regulating range after the enabling time and driving conditions. A thermostat stuck open is common, but prove the warm-up pattern: after a genuine overnight cold soak, intake-air and coolant readings should begin near ambient. Then graph coolant temperature, vehicle speed, load and heater/fan behavior. An ECT sensor biased cold, trapped air, low coolant, fans running when they should not, or an incorrect thermostat can mimic slow warm-up. The often-cited Toyota T-SB-0045-13 is a 2010–2011 Camry 2AR-FE bulletin—not a Highlander repair instruction.",symptoms:[{key:"heat",label:"Cabin heat is weak",response:"Check coolant level cold, then graph warm-up and heater-hose behavior."},{key:"highway",label:"Temperature drops on highway",response:"A thermostat unable to regulate becomes more likely; confirm with scan data."},{key:"normal",label:"Gauge looks normal",response:"The dash gauge is damped; use the ECT PID for diagnostic resolution."},{key:"hot",label:"Temperature rises too high",response:"Stop and diagnose as an overheating problem rather than continuing a P0128 test."}],causes:[{cause:"Thermostat stuck open or incorrect",evidence:"Slow curve and temperature falls with airflow",firstTest:"Record cold-start warm-up curve"},{cause:"ECT sensor or circuit biased cold",evidence:"Cold-soak mismatch or implausible jumps",firstTest:"Compare ECT/IAT/ambient and inspect circuit"},{cause:"Low coolant or trapped air",evidence:"Level loss, erratic heat or recent cooling work",firstTest:"Cold pressure/leak check and correct bleeding"},{cause:"Cooling fans operating unnecessarily",evidence:"Fans run cold without A/C or valid command",firstTest:"Check fan command, relays and related codes"},{cause:"ECM expectation affected by another fault",evidence:"Companion sensor/load code or unsuitable test",firstTest:"Resolve prerequisite faults and retest"}],freezeFrame:["ECT, intake-air and ambient temperature","Time since start, rpm, load and speed","Cooling-fan command and A/C request","Coolant level and recent service history","Heater output and outside temperature","Other temperature or sensor codes"],steps:[{title:"Begin from a true cold soak",detail:"Before starting, compare ECT and IAT to known ambient temperature."},{title:"Inspect the cooling system cold",detail:"Check reservoir/radiator procedure, leaks and evidence of trapped air safely."},{title:"Graph the complete warm-up",detail:"Watch rise rate, thermostat-opening behavior and highway temperature stability."},{title:"Check fan logic",detail:"Unwanted fan operation can remove enough heat to delay warm-up."},{title:"Verify the correct thermostat",detail:"Opening specification, sealing and installation must match the engine and year."},{title:"Repeat under comparable conditions",detail:"Confirm normal regulation and monitor completion without pending P0128."}],dontReplace:"Do not replace the thermostat solely because it is the common cause, and do not apply a Camry calibration bulletin to a Highlander. A biased ECT signal or low coolant can create the same code while requiring a very different repair.",yearNotes:["The 2AZ-FE, 1AR-FE, 2GR variants, A25A hybrid and turbo powertrains do not share one thermostat layout or bleeding procedure.","Hybrid engines cycle off normally, so Toyota's hybrid-specific warm-up logic and service mode matter.","Cold climate and heavy heater use influence warm-up time but do not erase a repeatable failed monitor.","T-SB-0045-13 frequently found online applies to specified Camry vehicles, not Highlander."],faqs:[{question:"Is P0128 always a thermostat?",answer:"No. Sensor bias, low coolant, air, fan operation and incorrect parts can mimic a stuck-open thermostat."},{question:"Can I drive?",answer:"Usually briefly if temperature is stable and coolant is full, but stop for overheating or coolant loss."},{question:"Why does the gauge look normal?",answer:"Dashboard gauges often suppress small changes; scan data shows the actual diagnostic trend."},{question:"Will fuel economy suffer?",answer:"It can, because prolonged warm-up may keep enrichment and emissions strategies active longer."},{question:"Can cold weather set it?",answer:"Cold weather affects warm-up, but the monitor accounts for enabling conditions; a repeatable code still needs diagnosis."},{question:"Does the Camry bulletin apply?",answer:"No. T-SB-0045-13 names 2010–2011 Camry 2AR-FE applications."},{question:"Should coolant be checked hot?",answer:"No. Follow Toyota's cold-check procedure; opening a hot pressurized system can cause severe burns."},{question:"What confirms repair?",answer:"A plausible cold-soak start, normal temperature rise and stable regulation with no pending code."}],deepDive:[{heading:"The cold-soak comparison catches sensor bias early",paragraphs:["After enough time parked, ECT and IAT should be reasonably close to ambient. A large disagreement before the engine starts cannot be caused by a stuck-open thermostat.","Record the numbers rather than relying on a blue or mid-scale dash indication. A smooth but biased sensor can mislead the ECM without obvious gauge movement."]},{heading:"Highway cooling is a useful clue",paragraphs:["A thermostat that cannot close may allow temperature to fall as road speed and radiator airflow increase. Capture speed, load and ECT together.","Do not create a long road test if coolant is low or temperature is unstable. Resolve safety and leakage concerns first."]},{heading:"Hybrid engine-off time needs correct interpretation",paragraphs:["The gasoline engine may stop while the hybrid system remains ready, naturally changing heat input. Toyota's model-specific monitor accounts for its control strategy.","Do not compare a hybrid warm-up trace directly with a conventional V6 or force the engine to run without the prescribed service procedure."]}],sources:[manuals,tis]}),

article({slug:"p1604",code:"P1604",title:"P1604 Code Toyota Highlander: Startability Malfunction",description:"Diagnose Highlander P1604 from the failed-start event: battery, cranking speed, fuel pressure, air, ignition and exact 2014–2018 connector bulletin checks.",definition:"Startability Malfunction",severity:"Diagnose promptly",driveAdvice:"If the Highlander repeatedly stalls, will not restart, loses fuel pressure or shows hybrid-system warnings, move it to a safe location and arrange diagnosis rather than repeatedly cranking. One historical P1604 after a discharged battery may permit normal operation, but preserve data and confirm reliable starting before depending on the vehicle.",quickAnswer:"Toyota P1604 records that the engine did not start or stabilize as expected; it is an event code, not a starter-motor diagnosis. First determine whether the engine cranked normally, cranked slowly, started then died, or never received a start request. Check battery voltage and cranking rpm, immobilizer/authorization and companion codes, then verify fuel pressure, MAF/throttle data, ignition and mechanical compression. For 2014–2018 Highlander and Highlander Hybrid, T-SB-0072-19 identifies a special branch: damaged or poorly sealed aftermarket windshield-deicer harnesses can admit water to specified connectors and cause drivability codes including P1604. T-SB-0009-23 supplies a separate fuel-pressure branch for specifically covered 2017–2019 applications.",symptoms:[{key:"slow",label:"Cranks slowly or clicks",response:"Load-test the 12-volt battery and inspect voltage drop before fuel parts."},{key:"fast",label:"Cranks normally but will not fire",response:"Check rpm/sync, fuel pressure, injector command and spark safely."},{key:"dies",label:"Starts then stalls",response:"Save elapsed time, MAF/throttle, pressure and immobilizer data."},{key:"rain",label:"Intermittent after rain or deicer installation",response:"On 2014–2018, inspect the exact water-intrusion path in T-SB-0072-19."}],causes:[{cause:"Weak 12-volt battery or excessive voltage drop",evidence:"Low cranking voltage/speed or failed conductance/load test",firstTest:"Battery test and positive/ground voltage drop"},{cause:"Fuel-pressure loss",evidence:"Extended crank with pressure below command/specification",firstTest:"Correct low/high-side pressure test"},{cause:"Air metering, purge or throttle problem",evidence:"Implausible MAF/throttle or post-refuel pattern",firstTest:"Inspect intake and graph start data"},{cause:"Ignition, crank signal or mechanical compression",evidence:"No sync/spark or abnormal relative compression",firstTest:"Cranking waveform and relative compression"},{cause:"Connector corrosion from deicer harness water path",evidence:"Matched 2014–2018 vehicle and installation/connector evidence",firstTest:"Follow T-SB-0072-19"}],freezeFrame:["Battery voltage and cranking rpm","Engine-run time before stall","Fuel pressure commanded versus actual","MAF, throttle angle and coolant temperature","Immobilizer, crank/cam, misfire and communication codes","Weather, windshield accessory history and fuel level"],steps:[{title:"Define what 'did not start' means",detail:"No-crank, slow-crank, crank/no-start and start/stall require different trees."},{title:"Test the 12-volt foundation",detail:"Measure battery health and voltage drop under the actual start attempt."},{title:"Preserve start-event data",detail:"Save all modules and freeze frame before repeated attempts alter the symptom."},{title:"Verify air, fuel, spark and compression",detail:"Use simultaneous data where possible instead of changing parts one system at a time."},{title:"Apply exact Highlander bulletins",detail:"Inspect the deicer-harness water path and fuel-pump applicability only when year/VIN match."},{title:"Cold-start more than once",detail:"Confirm a reliable soak restart and no pending startability code."}],dontReplace:"Do not replace the starter, fuel pump or ECM from P1604 alone. The code describes unsuccessful starting. Prove which requirement disappeared, and remember that connector corrosion can create multiple misleading codes while a weak 12-volt battery can distort every cranking measurement.",yearNotes:["2014–2018: T-SB-0072-19 includes P1604 among possible connector-corrosion symptoms related to certain aftermarket deicer harnesses.","2017–2019: T-SB-0009-23 includes defined Highlander/Highlander Hybrid fuel-pump applications; verify VIN/VDS.","Hybrid READY behavior differs from conventional cranking; use hybrid-capable scan data and safety procedures.","One code after battery service should be interpreted with voltage history, not automatically treated as an active engine defect."],faqs:[{question:"Does P1604 mean the starter is bad?",answer:"No. It means the start event failed; battery, authorization, fuel, air, ignition, signals and compression all matter."},{question:"Can a weak battery set it?",answer:"Yes. Low cranking voltage or speed can prevent the engine from stabilizing and create companion faults."},{question:"Can low fuel pressure cause it?",answer:"Yes. Measure pressure during the failed start, not only after the engine eventually runs."},{question:"Why inspect aftermarket windshield wiring?",answer:"Toyota documented a water path on certain 2014–2018 installations that can corrode key connectors."},{question:"Is the fuel pump covered?",answer:"Only if the exact vehicle falls within program applicability and diagnosis supports pressure loss."},{question:"Can I keep trying to start it?",answer:"Repeated attempts can drain the battery, overheat the starter and erase the original pattern; diagnose instead."},{question:"Can P1604 be historical?",answer:"Yes. Review occurrence, companion codes and current starting performance before deciding it is active."},{question:"What confirms repair?",answer:"Normal voltage and cranking data plus repeatable cold/hot starts with no pending event code."}],deepDive:[{heading:"Startability diagnosis begins with classification",paragraphs:["A silent no-crank is electrically different from normal-speed cranking with no combustion. 'It would not start' is not enough detail to select a test.","Record sound, cranking rpm, security indicators and whether the engine briefly catches. Those observations prevent wasted fuel and ignition work."]},{heading:"Capture fuel pressure during the failure",paragraphs:["A vehicle that starts on the second attempt may show normal pressure after the rail has recovered. Graph pressure from key-on or READY request through the failed event.","T-SB-0009-23 has exact model/VDS coverage. Use it to support, not replace, measurement."]},{heading:"Water intrusion creates code combinations",paragraphs:["T-SB-0072-19 explains why P1604 may coexist with lean, misfire, fuel-pressure or communication codes. Shared connector corrosion can interrupt several signals.","Repair must address both corrosion and the water path. Replacing a component downstream of a wet connector leaves recurrence likely."]}],sources:[waterTsb,fuelTsb,manuals,tis]}),

article({slug:"p0101",code:"P0101",title:"P0101 Code Toyota Highlander: MAF Range/Performance Diagnosis",description:"Diagnose Highlander P0101 with intake sealing, airflow plausibility and fuel-trim tests; account for V6, hybrid and turbo system differences.",definition:"Mass or Volume Air Flow Circuit Range/Performance",severity:"Diagnose promptly",driveAdvice:"A steady light with normal operation may allow a short diagnostic drive. Stop for stalling in traffic, severe hesitation, flashing misfire lamp or turbo/engine warnings. Avoid towing and hard acceleration because incorrect airflow information can disrupt fueling and load control.",quickAnswer:"P0101 means measured MAF airflow did not agree with the ECM's expected airflow for engine speed, throttle, pressure and load. It is a plausibility code, not proof that the MAF sensor is defective. Inspect the air filter and the full tract from air box to throttle/turbo for leaks, collapse, poor fit and aftermarket changes. Compare MAF, MAP, throttle, fuel trims and calculated load at a true key-on/engine-off baseline, hot idle and a controlled speed. A post-MAF leak often produces positive trims; contamination can under-report broadly; an engine breathing, EGR/VVT or turbo problem can make a healthy sensor look implausible.",symptoms:[{key:"idle",label:"Rough idle with positive trims",response:"Smoke-test the post-MAF tract and check PCV/purge paths."},{key:"load",label:"Hesitation when accelerating",response:"Graph airflow, pressure and trims; inspect duct collapse or turbo plumbing on applicable engines."},{key:"after",label:"Code followed filter/intake service",response:"Recheck filter seating, air-box clips, connector and duct clamps."},{key:"normal",label:"MIL only, no symptom",response:"Preserve freeze frame and run plausibility comparisons before cleaning or replacing."}],causes:[{cause:"Leak or restriction in the measured-air tract",evidence:"Smoke leak, loose duct or airflow changes with inspection",firstTest:"Visual inspection and smoke test"},{cause:"Contaminated or biased MAF element",evidence:"Airflow implausible with verified intake and circuit",firstTest:"Compare MAF to load/MAP and known operating points"},{cause:"MAF wiring, power or ground defect",evidence:"Dropout, reference/ground error or harness sensitivity",firstTest:"Loaded circuit and wiggle test"},{cause:"PCV/purge air bypass",evidence:"Idle-sensitive trims or post-refuel behavior",firstTest:"PCV integrity and purge closed-state test"},{cause:"Mechanical/VVT/turbo airflow mismatch",evidence:"Low compression, cam codes or boost pressure discrepancy",firstTest:"Engine-specific breathing and pressure diagnosis"}],freezeFrame:["MAF airflow, MAP and calculated load","Throttle angle, rpm and vehicle speed","Both-bank short/long fuel trims","Coolant and intake-air temperature","Boost command/actual on turbo applications","Recent air-filter, intake or engine work"],steps:[{title:"Inspect the complete intake",detail:"Look for wrong filters, unlatched boxes, cracks, loose clamps and disconnected resonators."},{title:"Check key-on baselines",detail:"MAP and temperature values should be plausible before the engine changes them."},{title:"Compare airflow at several states",detail:"Use hot idle and a controlled rpm/load point; one snapshot cannot establish a trend."},{title:"Use fuel trims as supporting evidence",detail:"They help distinguish unmetered air from a pure signal or breathing problem."},{title:"Test circuit integrity",detail:"Verify power, ground and signal under vibration and heat; connector appearance is not a voltage-drop test."},{title:"Verify without adaptations masking the fault",detail:"After repair and required reset, repeat the original load and confirm pending status stays clear."}],dontReplace:"Do not replace the MAF because P0101 includes its name, and do not spray it before recording data. Cleaning can temporarily change evidence and can damage the element if the wrong chemical or physical contact is used.",yearNotes:["Older naturally aspirated four-cylinder and V6 Highlanders have different expected airflow from A25A hybrid and newer turbo systems.","Hybrid engine-off events must be excluded when comparing airflow against vehicle speed.","Turbocharged applications require charge-pipe, bypass and boost-pressure checks in addition to the air box and MAF duct.","Aftermarket oiled filters and altered intake geometry are relevant history, not automatic proof of failure."],faqs:[{question:"Does P0101 mean replace the MAF?",answer:"No. Intake leaks, restrictions, wiring and engine airflow problems can make a good sensor fail plausibility."},{question:"Can I clean it?",answer:"Only after preserving data and confirming contamination; use an approved product and never touch the element."},{question:"Can a dirty air filter cause it?",answer:"A severe restriction or poor fit can affect airflow, but test the complete tract and data."},{question:"Can a vacuum leak cause P0101?",answer:"Yes. Air entering after the MAF is unmeasured and often raises positive fuel trims."},{question:"Why did it appear after service?",answer:"An unlatched air box, loose clamp, disconnected hose or damaged connector is a strong first check."},{question:"Can I drive?",answer:"Limit driving if it hesitates or stalls; avoid towing and stop for a flashing lamp."},{question:"Is MAF grams/second universal?",answer:"No. Displacement, rpm, load, altitude, hybrid operation and boost all affect expected flow."},{question:"What confirms repair?",answer:"Plausible airflow/load agreement, controlled trims and no pending P0101 under the original condition."}],deepDive:[{heading:"P0101 is a rationality judgment",paragraphs:["The sensor can produce a valid electrical signal that is still wrong for the engine's operating state. The ECM compares it with other load information.","That makes cross-PID agreement more useful than a single voltage or grams-per-second number copied from another engine."]},{heading:"Fuel trims help, but do not diagnose alone",paragraphs:["Strong positive trims that improve when an intake leak is isolated support unmetered air. Near-normal trims with implausible load can shift attention to signal or engine breathing.","Evaluate both banks on a V6. A large bank split is less consistent with one shared MAF sensor than equal movement on both banks."]},{heading:"Turbo and hybrid models need separate logic",paragraphs:["A turbo Highlander can leak or restrict airflow on either side of the compressor, and pressure data becomes part of the plausibility check.","A hybrid can travel with the engine stopped. Match MAF data to engine-running periods rather than vehicle motion alone."]}],sources:[manuals,tis]}),

article({slug:"p0138",code:"P0138",title:"P0138 Code Toyota Highlander: Bank 1 Sensor 2 High Voltage",description:"Diagnose Highlander P0138 using exact Bank 1 Sensor 2 data, wiring and mixture tests, including Toyota's limited 2008–2010 2GR-FE diagnostic bulletin.",definition:"Oxygen Sensor Circuit High Voltage (Bank 1 Sensor 2)",severity:"Diagnose promptly",driveAdvice:"A steady P0138 with normal operation usually allows a short diagnostic trip. Stop for a flashing misfire lamp, raw-fuel odor, smoke, severe roughness or an overheating catalyst. Rich operation can damage the converter, while a circuit short may affect other shared references.",quickAnswer:"P0138 means the ECM saw Bank 1 Sensor 2—the downstream oxygen-sensor circuit—remain too high for the monitored condition. Possibilities include a genuinely rich exhaust, contamination, an exhaust/sensor issue or a signal short. Do not immediately replace the downstream sensor. Toyota T-SB-0001-10 Rev1 gives a particularly important diagnostic branch for 2008–2010 Highlander 2GR-FE: after checking companion codes, technicians compare exact freeze-frame A/F Sensor Bank 1 Sensor 1 and O2 Sensor Bank 1 Sensor 2 values. When the bulletin's precise value window is met, Toyota directs replacement of the upstream A/F sensor only, not the downstream O2 sensor. Outside that window—or on other years/engines—follow normal circuit diagnosis.",symptoms:[{key:"normal",label:"MIL on, engine feels normal",response:"Save freeze frame and compare upstream/downstream values before clearing."},{key:"rich",label:"Fuel odor, smoke or poor economy",response:"Check fuel trims, misfire and injector/purge causes; protect the catalyst."},{key:"other",label:"P2195/P2197 or P0606 also stored",response:"On a matched 2008–2010 2GR-FE, follow T-SB-0001-10's companion-code sequence exactly."},{key:"after",label:"Code followed exhaust or wiring work",response:"Inspect routing, connector identity, heat damage and signal shorts first."}],causes:[{cause:"Bank 1 Sensor 2 signal short/high-resistance circuit issue",evidence:"Voltage remains high with controlled circuit tests",firstTest:"Inspect and electrically test signal/ground wiring"},{cause:"Rich exhaust from fuel, purge or misfire fault",evidence:"Negative trims, fuel odor, deposits or companion codes",firstTest:"Fuel-control and injector/purge diagnosis"},{cause:"Upstream A/F sensor fault in exact bulletin window",evidence:"2008–2010 2GR-FE plus specified FFD values",firstTest:"Follow T-SB-0001-10 decision tree"},{cause:"Downstream sensor contaminated or failed",evidence:"Circuit passes but controlled response remains wrong",firstTest:"Engine-specific sensor response test"},{cause:"Connector swap, water or exhaust damage",evidence:"Recent repair, melted harness or contamination",firstTest:"Trace Bank 1 Sensor 2 circuit physically"}],freezeFrame:["A/F Sensor B1S1 voltage/current as supported","O2 Sensor B1S2 voltage","Both-bank fuel trims","RPM, load, coolant temperature and speed","P2195/P2197, P0606, misfire and mixture codes","Recent exhaust, engine or wiring work"],steps:[{title:"Confirm Bank 1 Sensor 2",detail:"Use the exact engine diagram; Bank 1 contains cylinder 1 and Sensor 2 is downstream."},{title:"Save all freeze-frame values",detail:"The 2008–2010 bulletin depends on exact paired sensor readings and companion codes."},{title:"Decide whether exhaust is truly rich",detail:"Review trims, plugs, fuel pressure, purge and injector behavior before blaming the circuit."},{title:"Inspect the hot-zone harness",detail:"Look for melted insulation, connector damage and incorrect routing near the exhaust."},{title:"Apply T-SB-0001-10 only when exact",detail:"Its value window can point to the upstream A/F sensor even though P0138 names the downstream circuit."},{title:"Run a controlled response test",detail:"Verify the correct sensor changes and the code remains absent after monitor completion."}],dontReplace:"Do not replace Bank 1 Sensor 2 solely from the code title. On the exact 2008–2010 2GR-FE bulletin branch, Toyota may direct replacement of the upstream A/F sensor instead. On every application, confirm rich operation and circuit integrity before parts.",yearNotes:["2008–2010 Highlander 2GR-FE: T-SB-0001-10 Rev1 supplies exact freeze-frame and companion-code diagnostic logic.","The bulletin does not cover every Highlander year, four-cylinder, hybrid or turbo powertrain.","Bank 1 location must be identified by cylinder 1 on the exact engine, not a universal front/rear claim.","Sensor terminology matters: Toyota A/F sensors upstream do not behave like conventional narrowband downstream O2 sensors."],faqs:[{question:"Is P0138 the downstream sensor?",answer:"The code monitors Bank 1 Sensor 2, but the root cause can be wiring, rich exhaust or—under Toyota's exact bulletin logic—the upstream A/F sensor."},{question:"Which side is Bank 1?",answer:"The bank containing cylinder 1; confirm with the VIN-correct engine diagram."},{question:"Can I drive?",answer:"Usually briefly if operation is normal, but stop for flashing misfire, smoke or raw-fuel odor."},{question:"Can a leaking injector cause it?",answer:"Yes. A truly rich exhaust can keep downstream oxygen-sensor voltage high."},{question:"Can a purge valve cause it?",answer:"A purge valve admitting excessive vapor can enrich the mixture, particularly around refueling events."},{question:"Does the bulletin cover a 2012 Highlander?",answer:"No. The cited application includes 2008–2010 Highlander 2GR-FE."},{question:"Why would Toyota replace the upstream sensor?",answer:"The bulletin's exact paired freeze-frame pattern identifies an upstream A/F measurement fault that can drive the downstream reading/code logic."},{question:"What confirms repair?",answer:"Correct fuel control, sound wiring, normal controlled sensor response and no pending P0138."}],deepDive:[{heading:"The official bulletin reverses the obvious parts guess",paragraphs:["T-SB-0001-10 tells technicians to check all DTCs and compare A/F B1S1 with O2 B1S2 in freeze frame. In its defined window, the appropriate repair is the upstream A/F sensor only.","This is exactly why code-title parts replacement fails. The branch depends on model, year, engine, companion codes and exact values—not just P0138."]},{heading:"Separate a rich exhaust from a high circuit",paragraphs:["Negative fuel trims, fuel odor, deposits and both-bank behavior support a real rich condition. A signal pinned high despite controlled mixture changes points back toward sensor/circuit testing.","Correct rich operation before prolonged road testing. Raw fuel can overheat and damage the catalyst."]},{heading:"Connector identity and routing matter",paragraphs:["Multiple similar connectors near a V6 exhaust can be misrouted or swapped after repair. Trace the circuit rather than trusting reach or color alone.","Heat shields and clips protect the harness. A repaired wire left against the exhaust may pass briefly and fail again as insulation softens."]}],sources:[o2Tsb,manuals,tis]}),
];
